DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$pilot$PT110-S2-Q8$pilot$ AND c.letter=$pilot$B$pilot$ AND c.choice_text=$pilot$questioning the conservationist’s motives for reaching a certain conclusion$pilot$) THEN RAISE EXCEPTION 'Choice changed: PT110-S2-Q8 B'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$pilot$PT110-S2-Q8$pilot$ AND c.letter=$pilot$C$pilot$ AND c.choice_text=$pilot$asserting that dangerous situations inevitably become more dangerous with the passage of time$pilot$) THEN RAISE EXCEPTION 'Choice changed: PT110-S2-Q8 C'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$pilot$PT110-S2-Q8$pilot$ AND c.letter=$pilot$D$pilot$ AND c.choice_text=$pilot$discrediting the moral principle on which the conservationist’s argument is based$pilot$) THEN RAISE EXCEPTION 'Choice changed: PT110-S2-Q8 D'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$pilot$PT110-S2-Q8$pilot$ AND c.letter=$pilot$E$pilot$ AND c.choice_text=$pilot$disputing the accuracy of the figures cited by the conservationist$pilot$) THEN RAISE EXCEPTION 'Choice changed: PT110-S2-Q8 E'; END IF; END $guard$;
