INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$pilot$PT110-S2-Q8$pilot$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $pilot$Conservationist's Conclusion (therefore)$pilot$, $pilot$The wildlife refuge poses no safety risk to airplane passengers.$pilot$), (1, $pilot$Conservationist's Evidence$pilot$, $pilot$In 10 years, only 20 planes have been damaged by birds from the refuge, and no passenger has been hurt.$pilot$), (2, $pilot$Pilot's Response$pilot$, $pilot$17 of those 20 collisions happened in the last 2 years, and the bird population is growing fast. More collisions means a higher chance one of them hurts a passenger.$pilot$), (3, $pilot$Evaluate$pilot$, $pilot$First question on any two-speaker Method: was the second person adding to the first person's argument or pushing back? Pushing back, clearly. So next: pushing back on what?

Notice what the pilot does *not* say. He doesn't say "it wasn't 20 collisions" or "someone actually got hurt." He accepts every number the conservationist gave.

What he attacks is the picture those numbers paint. "20 collisions in 10 years" sounds like 2 a year, steady and harmless. But 17 of them happened in the last 2 years, so the real rate is about 8 a year and climbing. The 10-year average hides a trend.

This is the most common way a second speaker pushes back on the LSAT. They almost never deny the first speaker's evidence. They accept it and add a fact that changes what it means.$pilot$), (4, $pilot$Goal$pilot$, $pilot$Look for something like: "The pilot accepts the conservationist's facts but argues they were presented in a way that gives the wrong impression."$pilot$)) v(position,label,body) WHERE q.qid=$pilot$PT110-S2-Q8$pilot$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($pilot$A$pilot$, $pilot$"Misleading" is the right word. The conservationist's facts are accurate, but her description (20 over 10 years, no injuries) leaves out the timing that makes the refuge look safe. The pilot supplies the missing piece to show the risk is growing fast.$pilot$), ($pilot$B$pilot$, $pilot$The pilot never suggests the conservationist has a hidden agenda. He doesn't say "you just want to protect the birds." He argues with her reasoning, not her motives.$pilot$), ($pilot$C$pilot$, $pilot$This is the most popular wrong answer, for students who notice the pilot is talking about the future. But the pilot's point is specific: collisions are rising *because* the bird population is rising. He never says dangerous situations *inevitably* get worse with the passage of time. Time isn't the cause in his argument. More birds is. And "dangerous situations" in general is far broader than this one airport.$pilot$), ($pilot$D$pilot$, $pilot$There's no moral principle in the conservationist's argument. Safety risk is a factual question. There's nothing for the pilot to discredit.$pilot$), ($pilot$E$pilot$, $pilot$In almost every Method of Response question, one answer says the second speaker disputes or denies the first speaker's evidence. It's almost never right, and it isn't here. The pilot doesn't dispute the figures. He relies on them: "17 of *those* 20 collisions" only works if the 20 is accurate.$pilot$)) v(letter,body) WHERE q.qid=$pilot$PT110-S2-Q8$pilot$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_note